#!/bin/bash
set -e
if [[ $EUID -ne 0 ]]; then echo "Ruleaza ca root (sudo su)!"; exit 1; fi
clear
echo "=========================================================="
echo "   INSTALARE COMPLETA SSH PLUS MANAGER RO (22/24/26.04)   "
echo "=========================================================="
read -p "Introdu domeniul (ex: ://1monzo.com): " DOMAIN
read -p "Introdu emailul pentru SSL (ex: dobrin.nsa@gmail.com): " EMAIL
[[ -z "$DOMAIN" || -z "$EMAIL" ]] && { echo "Domeniu si email obligatorii!"; exit 1; }
export DEBIAN_FRONTEND=noninteractive
apt-get update -y
apt-get install -y python3 stunnel4 certbot curl wget git psmisc net-tools cmake build-essential cron iptables-persistent
mkdir -p /etc/SSHPlus /run/sshplus_conn /etc/stunnel /etc/letsencrypt/renewal-hooks/post
chmod 777 /run/sshplus_conn
grep -qxF '/bin/false' /etc/shells || echo '/bin/false' >> /etc/shells
grep -qxF '/usr/sbin/nologin' /etc/shells || echo '/usr/sbin/nologin' >> /etc/shells
sed -i 's/PasswordAuthentication no/PasswordAuthentication yes/g' /etc/ssh/sshd_config /etc/ssh/sshd_config.d/*.conf 2>/dev/null || true
echo "PasswordAuthentication yes" > /etc/ssh/sshd_config.d/99-allow-password.conf
systemctl restart ssh 2>/dev/null || systemctl restart sshd 2>/dev/null || true
if [[ ! -f /usr/local/bin/badvpn-udpgw ]]; then
    git clone --depth 1 https://github.com /tmp/badvpn 2>/dev/null || true
    if [[ -d /tmp/badvpn ]]; then
        mkdir -p /tmp/badvpn/build && cd /tmp/badvpn/build
        cmake .. -DCMAKE_POLICY_VERSION_MINIMUM=3.5 -DCMAKE_C_FLAGS="-O2 -Wno-error -Wno-implicit-function-declaration -Wno-int-conversion -Wno-incompatible-pointer-types" -DBUILD_NOTHING_BY_DEFAULT=1 -DBUILD_UDPGW=1 >/dev/null 2>&1
        make -j"$(nproc)" >/dev/null 2>&1
        cp udpgw/badvpn-udpgw /usr/local/bin/badvpn-udpgw && chmod +x /usr/local/bin/badvpn-udpgw
        cd /root && rm -rf /tmp/badvpn
    fi
fi
mkdir -p '/etc/SSHPlus'
echo '' | base64 -d > '/etc/SSHPlus/wsproxy.py'
chmod +x '/etc/SSHPlus/wsproxy.py'
mkdir -p '/etc/SSHPlus'
echo '' | base64 -d > '/etc/SSHPlus/dispatcher.py'
chmod +x '/etc/SSHPlus/dispatcher.py'
mkdir -p '/etc/SSHPlus'
echo '' | base64 -d > '/etc/SSHPlus/get_vpn_users.sh'
chmod +x '/etc/SSHPlus/get_vpn_users.sh'
mkdir -p '/etc/SSHPlus'
echo '' | base64 -d > '/etc/SSHPlus/traffic_tracker.sh'
chmod +x '/etc/SSHPlus/traffic_tracker.sh'
mkdir -p '/etc/SSHPlus'
echo '' | base64 -d > '/etc/SSHPlus/colors'
chmod +x '/etc/SSHPlus/colors'
mkdir -p '/usr/bin'
echo '' | base64 -d > '/usr/bin/menu'
chmod +x '/usr/bin/menu'
mkdir -p /etc/SSHPlus /usr/bin
echo '' | base64 -d > '/etc/SSHPlus/adblock_proxy.py'
chmod +x '/etc/SSHPlus/adblock_proxy.py'
echo '' | base64 -d > '/usr/bin/adblockdns'
chmod +x '/usr/bin/adblockdns'

echo '' | base64 -d > '/usr/bin/adblockdns'
chmod +x '/usr/bin/adblockdns'

echo '' | base64 -d > '/usr/bin/domainmanager'
chmod +x '/usr/bin/domainmanager'
mkdir -p /etc/stunnel/certs

mkdir -p '/usr/bin'
echo '' | base64 -d > '/usr/bin/createuser'
chmod +x '/usr/bin/createuser'
mkdir -p '/usr/bin'
echo '' | base64 -d > '/usr/bin/changelimit'
chmod +x '/usr/bin/changelimit'
mkdir -p '/usr/bin'
echo '' | base64 -d > '/usr/bin/removeuser'
chmod +x '/usr/bin/removeuser'
mkdir -p '/usr/bin'
echo '' | base64 -d > '/usr/bin/sshmonitor'
chmod +x '/usr/bin/sshmonitor'
mkdir -p '/usr/bin'
echo '' | base64 -d > '/usr/bin/expirationmanager'
chmod +x '/usr/bin/expirationmanager'
mkdir -p '/usr/bin'
echo '' | base64 -d > '/usr/bin/userips'
chmod +x '/usr/bin/userips'
mkdir -p '/usr/bin'
echo '' | base64 -d > '/usr/bin/changepassword'
chmod +x '/usr/bin/changepassword'
mkdir -p '/usr/bin'
echo '' | base64 -d > '/usr/bin/userbackup'
chmod +x '/usr/bin/userbackup'
systemctl stop ws-proxy-80 ws-proxy-8080 ws-dispatcher 2>/dev/null || true
fuser -k 80/tcp 8080/tcp 8081/tcp 2>/dev/null || true
certbot certonly --standalone -d "$DOMAIN" --non-interactive --agree-tos -m "$EMAIL"
cat "/etc/letsencrypt/live/${DOMAIN}/fullchain.pem" "/etc/letsencrypt/live/${DOMAIN}/privkey.pem" > /etc/stunnel/stunnel.pem
chmod 600 /etc/stunnel/stunnel.pem
printf "pid = /var/run/stunnel.pid\ncert = /etc/stunnel/stunnel.pem\nclient = no\n[https]\naccept = 443\nconnect = 127.0.0.1:8081\n" > /etc/stunnel/stunnel.conf
sed -i 's/ENABLED=0/ENABLED=1/g' /etc/default/stunnel4 2>/dev/null || true
printf "#!/bin/bash\ncat /etc/letsencrypt/live/${DOMAIN}/fullchain.pem /etc/letsencrypt/live/${DOMAIN}/privkey.pem > /etc/stunnel/stunnel.pem\nchmod 600 /etc/stunnel/stunnel.pem\nkillall -9 stunnel4 2>/dev/null || true\n/usr/bin/stunnel4 /etc/stunnel/stunnel.conf\nsystemctl start ws-proxy-80\n" > /etc/letsencrypt/renewal-hooks/post/restart-services.sh
chmod +x /etc/letsencrypt/renewal-hooks/post/restart-services.sh
printf "[Unit]\nDescription=WS 80\nAfter=network.target\n[Service]\nExecStart=/usr/bin/python3 /etc/SSHPlus/wsproxy.py -b 0.0.0.0 -p 80\nRestart=always\n[Install]\nWantedBy=multi-user.target\n" > /etc/systemd/system/ws-proxy-80.service
printf "[Unit]\nDescription=Disp 8081\nAfter=network.target\n[Service]\nExecStart=/usr/bin/python3 /etc/SSHPlus/dispatcher.py\nRestart=always\n[Install]\nWantedBy=multi-user.target\n" > /etc/systemd/system/ws-dispatcher.service
printf "[Unit]\nDescription=BadVPN 7300\nAfter=network.target\n[Service]\nExecStart=/usr/local/bin/badvpn-udpgw --listen-addr 127.0.0.1:7300 --max-clients 500\nRestart=always\n[Install]\nWantedBy=multi-user.target\n" > /etc/systemd/system/badvpn-udpgw.service
killall -9 stunnel4 2>/dev/null || true
/usr/bin/stunnel4 /etc/stunnel/stunnel.conf
(crontab -l 2>/dev/null | grep -v 'traffic_tracker.sh'; echo '* * * * * /etc/SSHPlus/traffic_tracker.sh >/dev/null 2>&1') | crontab -
systemctl daemon-reload
systemctl enable --now ws-proxy-80 ws-dispatcher badvpn-udpgw
iptables -I INPUT 1 -p tcp --dport 80 -j ACCEPT
iptables -I INPUT 2 -p tcp --dport 443 -j ACCEPT
iptables -I INPUT 3 -p tcp --dport 8080 -j ACCEPT
iptables -I INPUT 4 -p tcp --dport 7300 -j ACCEPT
netfilter-persistent save 2>/dev/null || true
echo "INSTALARE COMPLETA! Tasteaza: menu"
